/* ============================================================================
   Módulo: SOLICITUD DE ORDEN DE PEDIDO  (agrega a la BD RegistroCodigos)
   Motor: PostgreSQL (Azure Database for PostgreSQL - Flexible Server)
   Ejecutar DESPUÉS de RegistroCodigos.sql (reutiliza el esquema 'cat').
   Ejecutar con:  psql "<cadena-de-conexion>" -f OrdenPedido.sql
   ============================================================================ */
CREATE SCHEMA IF NOT EXISTS cat;
CREATE SCHEMA IF NOT EXISTS dbo;

/* Limpieza para re-ejecución */
DROP VIEW  IF EXISTS dbo.vOrdenPedido;
DROP TABLE IF EXISTS dbo.OrdenPedido;
DROP TABLE IF EXISTS cat.OP_Producto;
DROP TABLE IF EXISTS cat.OP_Bodega;
DROP TABLE IF EXISTS cat.OP_Proveedor;
DROP TABLE IF EXISTS cat.OP_Transporte;
DROP TABLE IF EXISTS cat.OP_Sector;

/* Catálogos del módulo (listas desplegables gestionables) */
CREATE TABLE cat.OP_Producto  (Id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, Nombre VARCHAR(400) NOT NULL UNIQUE, Activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE cat.OP_Bodega    (Id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, Nombre VARCHAR(120) NOT NULL UNIQUE, Activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE cat.OP_Proveedor (Id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, Nombre VARCHAR(200) NOT NULL UNIQUE, Activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE cat.OP_Transporte(Id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, Nombre VARCHAR(60)  NOT NULL UNIQUE, Activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE cat.OP_Sector    (Id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, Nombre VARCHAR(30)  NOT NULL UNIQUE, Activo BOOLEAN NOT NULL DEFAULT TRUE);

/* Tabla principal de órdenes */
CREATE TABLE dbo.OrdenPedido (
    Id                  INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ProductoId          INT NOT NULL,
    Descripcion         VARCHAR(400) NOT NULL,
    Cajas               INT NULL,
    UnidadesPorCaja     INT NULL,
    TotalUnidades       INT NULL,
    BodegaId            INT NULL,
    ProveedorId         INT NOT NULL,
    TransporteId        INT NULL,
    SectorId            INT NULL,
    FechaEntrega        DATE NULL,
    PrecioEspecial      DECIMAL(18,2) NULL,
    NumeroEMB           VARCHAR(100) NULL,
    FechaVencimientoEMB DATE NULL,
    Observaciones       TEXT NULL,
    Estado              VARCHAR(20) NOT NULL DEFAULT 'Pendiente'
                        CONSTRAINT CK_OrdenPedido_Estado CHECK (Estado IN ('Pendiente','Procesado')),
    CreadoPor           VARCHAR(200) NULL,
    FechaCreacion       TIMESTAMP(0) NOT NULL DEFAULT (now() at time zone 'utc'),
    ModificadoPor       VARCHAR(200) NULL,
    FechaModificacion   TIMESTAMP(0) NULL,
    CONSTRAINT FK_OP_Producto   FOREIGN KEY (ProductoId)   REFERENCES cat.OP_Producto(Id),
    CONSTRAINT FK_OP_Bodega     FOREIGN KEY (BodegaId)     REFERENCES cat.OP_Bodega(Id),
    CONSTRAINT FK_OP_Proveedor  FOREIGN KEY (ProveedorId)  REFERENCES cat.OP_Proveedor(Id),
    CONSTRAINT FK_OP_Transporte FOREIGN KEY (TransporteId) REFERENCES cat.OP_Transporte(Id),
    CONSTRAINT FK_OP_Sector     FOREIGN KEY (SectorId)     REFERENCES cat.OP_Sector(Id)
);
CREATE INDEX IX_OrdenPedido_Producto ON dbo.OrdenPedido(ProductoId);

/* Vista aplanada para el listado principal */
CREATE VIEW dbo.vOrdenPedido AS
SELECT o.Id, p.Nombre AS Producto, o.Descripcion, o.Cajas, o.TotalUnidades,
       b.Nombre AS Bodega, pr.Nombre AS Proveedor, o.FechaEntrega,
       o.Estado, o.FechaCreacion, o.CreadoPor
FROM dbo.OrdenPedido o
JOIN cat.OP_Producto  p  ON p.Id = o.ProductoId
LEFT JOIN cat.OP_Bodega    b  ON b.Id = o.BodegaId
JOIN cat.OP_Proveedor pr ON pr.Id = o.ProveedorId;

